import { strict as assert } from "node:assert";
import crypto from "node:crypto";
import { test } from "node:test";
import { Hono } from "hono";

process.env.DATABASE_URL ??= "postgres://localhost:5434/superlog";
process.env.BETTER_AUTH_SECRET ??= "test-better-auth-secret-with-enough-length";
process.env.GITHUB_APP_SLUG = "superlog-test";
process.env.SLACK_CLIENT_ID = "slack-client";
process.env.SLACK_CLIENT_SECRET = "slack-secret";
process.env.AGENT_SECRETS_KEY = Buffer.alloc(32, 1).toString("base64");
process.env.STATE_SIGNING_SECRET = "state-secret";
process.env.WEB_ORIGIN = "https://app.example.test";

const { mountGithubPublic } = await import("./github.js");
const { mountSlackPublic } = await import("./slack.js");

const device = {
  userId: "owner-user",
  orgId: "owner-org",
  projectId: "owner-project",
};

function installDependencies(currentUserId: () => string | null, canManage: () => boolean) {
  return {
    getAuthenticatedUserId: async () => currentUserId(),
    resolveDevice: () => device,
    hasProjectManagerAccess: async () => canManage(),
  };
}

test("Slack install kickoff rejects an unauthenticated browser", async () => {
  const app = new Hono();
  mountSlackPublic(
    app,
    installDependencies(
      () => null,
      () => true,
    ),
  );

  const response = await app.request("/slack/install?user_code=ABCD-EFGH");

  assert.equal(response.status, 401);
});

test("GitHub install kickoff rejects a user other than the device owner", async () => {
  const app = new Hono();
  mountGithubPublic(
    app,
    installDependencies(
      () => "other-user",
      () => true,
    ),
  );

  const response = await app.request("/github/install?user_code=ABCD-EFGH");

  assert.equal(response.status, 403);
});

test("Slack callback rejects a different authenticated user than the kickoff user", async () => {
  let userId: string | null = device.userId;
  let providerCalls = 0;
  const originalFetch = globalThis.fetch;
  globalThis.fetch = async () => {
    providerCalls++;
    return Response.json({ ok: false, error: "unexpected_exchange" });
  };

  try {
    const app = new Hono();
    mountSlackPublic(
      app,
      installDependencies(
        () => userId,
        () => true,
      ),
    );
    const kickoff = await app.request("/slack/install?user_code=ABCD-EFGH");
    const authorizationUrl = new URL(kickoff.headers.get("location") ?? "");
    const state = authorizationUrl.searchParams.get("state");
    assert.ok(state);

    userId = "other-user";
    const callback = await app.request(
      `/slack/oauth/callback?code=oauth-code&state=${encodeURIComponent(state)}`,
    );

    assert.equal(callback.status, 302);
    assert.equal(callback.headers.get("location"), "https://app.example.test/app?slack=error");
    assert.equal(providerCalls, 0);
  } finally {
    globalThis.fetch = originalFetch;
  }
});

test("GitHub callback rejects the initiating user after project access is revoked", async () => {
  let canManage = true;
  const app = new Hono();
  mountGithubPublic(
    app,
    installDependencies(
      () => device.userId,
      () => canManage,
    ),
  );
  const kickoff = await app.request("/github/install?user_code=ABCD-EFGH");
  const authorizationUrl = new URL(kickoff.headers.get("location") ?? "");
  const state = authorizationUrl.searchParams.get("state");
  assert.ok(state);

  canManage = false;
  const callback = await app.request(
    `/github/install/callback?installation_id=123&state=${encodeURIComponent(state)}`,
  );

  assert.equal(callback.status, 302);
  assert.equal(callback.headers.get("location"), "https://app.example.test/app?gh=error");
});

test("Slack callback rejects legacy device state without an initiating user", async () => {
  const body = `owner-org.owner-project..ABCD-EFGH.${Date.now()}`;
  const signature = crypto.createHmac("sha256", "state-secret").update(body).digest("base64url");
  const state = `${Buffer.from(body, "utf8").toString("base64url")}.${signature}`;
  const app = new Hono();
  mountSlackPublic(
    app,
    installDependencies(
      () => device.userId,
      () => true,
    ),
  );

  const callback = await app.request(
    `/slack/oauth/callback?code=oauth-code&state=${encodeURIComponent(state)}`,
  );

  assert.equal(callback.status, 302);
  assert.equal(callback.headers.get("location"), "https://app.example.test/app?slack=error");
});

test("GitHub callback rejects legacy state authorized only by a user code", async () => {
  const payload = `cli.ABCD-EFGH.${Date.now()}`;
  const signature = crypto.createHmac("sha256", "state-secret").update(payload).digest("base64url");
  const state = `${Buffer.from(payload, "utf8").toString("base64url")}.${signature}`;
  const app = new Hono();
  mountGithubPublic(
    app,
    installDependencies(
      () => device.userId,
      () => true,
    ),
  );

  const callback = await app.request(
    `/github/install/callback?installation_id=123&state=${encodeURIComponent(state)}`,
  );

  assert.equal(callback.status, 400);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import {
  authRateLimitMetricAttributes,
  authRateLimitMetricRoute,
} from "./auth-rate-limit-metrics.js";

test("rate-limit metrics contain only the stable auth route and environment", () => {
  assert.deepEqual(authRateLimitMetricAttributes("/api/auth/sign-in/email", "production"), {
    "http.route": "/api/auth/sign-in/email",
    "deployment.environment.name": "production",
  });
});

test("rate-limit metric routes have bounded cardinality", () => {
  assert.equal(authRateLimitMetricRoute("/api/auth/sign-in/email"), "/api/auth/sign-in/email");
  assert.equal(
    authRateLimitMetricRoute("/api/auth/sign-in/attacker-chosen-provider"),
    "/api/auth/sign-in/*",
  );
  assert.equal(authRateLimitMetricRoute("/api/auth/attacker-chosen-path"), "/api/auth/*");
});

import assert from "node:assert/strict";
import path from "node:path";
import { after, before, test } from "node:test";
import { fileURLToPath } from "node:url";
import { PGlite } from "@electric-sql/pglite";
import type { DB } from "@superlog/db";
import * as schema from "@superlog/db/schema";
import { drizzle } from "drizzle-orm/pglite";
import { migrate } from "drizzle-orm/pglite/migrator";
import { createDrizzleAuthRateLimitRepository } from "./auth-rate-limit-repository.js";

const key = `auth:global:test-${Date.now()}-${Math.random()}`;
const migrations = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../../../packages/db/migrations",
);
const client = new PGlite();
const pgliteDatabase = drizzle(client, { schema });
const database = pgliteDatabase as unknown as DB;

before(async () => {
  await migrate(pgliteDatabase, { migrationsFolder: migrations });
});

after(async () => {
  await client.close();
});

test("atomically caps concurrent requests and resets after the window", async () => {
  const repository = createDrizzleAuthRateLimitRepository(database);
  const nowEpochMs = 1_800_000_000_000;
  const input = { key, max: 60, windowMs: 60_000, nowEpochMs };

  const decisions = await Promise.all(Array.from({ length: 100 }, () => repository.consume(input)));

  assert.equal(decisions.filter((decision) => decision.allowed).length, 60);
  assert.equal(decisions.filter((decision) => !decision.allowed).length, 40);

  const reset = await repository.consume({ ...input, nowEpochMs: nowEpochMs + input.windowMs + 1 });
  assert.deepEqual(reset, { allowed: true, retryAfterSeconds: null });
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { enforceGlobalAuthRateLimit } from "./auth-global-rate-limit.js";

test("the global auth limit uses one per-IP bucket across every auth route", async () => {
  const calls: unknown[] = [];
  const response = await enforceGlobalAuthRateLimit(
    {
      consume: async (input) => {
        calls.push(input);
        return { allowed: false, retryAfterSeconds: 17 };
      },
    },
    "198.51.100.42",
    1_800_000_000_000,
  );

  assert.deepEqual(calls, [
    {
      key: "auth:global:198.51.100.42",
      max: 60,
      windowMs: 60_000,
      nowEpochMs: 1_800_000_000_000,
    },
  ]);
  assert.equal(response?.status, 429);
  assert.equal(response?.headers.get("retry-after"), "17");
});

test("the global auth limit falls through when the request is allowed", async () => {
  const response = await enforceGlobalAuthRateLimit(
    { consume: async () => ({ allowed: true, retryAfterSeconds: null }) },
    undefined,
    1_800_000_000_000,
  );

  assert.equal(response, null);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { startAuthRateLimitCleanup } from "./auth-rate-limit-cleanup.js";

test("cleans auth rate-limit rows older than the longest configured window on startup", async () => {
  const cutoffs: number[] = [];
  const errors: unknown[] = [];
  const now = () => 1_800_000_000_000;
  const stop = startAuthRateLimitCleanup({
    repository: {
      deleteBefore: async (cutoff) => {
        cutoffs.push(cutoff);
        return 2;
      },
    },
    now,
    intervalMs: 60_000,
    onError: (error) => errors.push(error),
  });

  await new Promise((resolve) => setImmediate(resolve));
  stop();

  assert.deepEqual(cutoffs, [now() - 60 * 60 * 1000]);
  assert.deepEqual(errors, []);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { betterAuth } from "better-auth";
import { memoryAdapter } from "better-auth/adapters/memory";
import { AUTH_CLIENT_IP_HEADER } from "./auth-client-ip.js";
import { AUTH_RATE_LIMIT } from "./auth-rate-limit.js";

test("email sign-in is limited to five attempts per IP in fifteen minutes", async () => {
  const auth = betterAuth({
    baseURL: "http://localhost:4100",
    secret: "a-very-long-test-only-better-auth-secret",
    database: memoryAdapter({ user: [], session: [], account: [], verification: [] }),
    advanced: { ipAddress: { ipAddressHeaders: [AUTH_CLIENT_IP_HEADER] } },
    rateLimit: { ...AUTH_RATE_LIMIT, storage: "memory" },
    emailAndPassword: { enabled: true },
  });
  const request = (ip = "198.51.100.11") =>
    auth.handler(
      new Request("http://localhost:4100/api/auth/sign-in/email", {
        method: "POST",
        headers: {
          "content-type": "application/json",
          [AUTH_CLIENT_IP_HEADER]: ip,
        },
        body: JSON.stringify({ email: "nobody@example.com", password: "invalid-password" }),
      }),
    );

  for (let attempt = 0; attempt < 5; attempt += 1) {
    assert.notEqual((await request()).status, 429);
  }

  const limited = await request();
  assert.equal(limited.status, 429);
  assert.ok(Number(limited.headers.get("x-retry-after")) > 0);
  assert.notEqual((await request("198.51.100.12")).status, 429);
});

test("rate limiting is always enabled with shared storage", () => {
  assert.equal(AUTH_RATE_LIMIT.enabled, true);
  assert.equal(AUTH_RATE_LIMIT.storage, "database");
  assert.equal(AUTH_RATE_LIMIT.customRules?.["*"], false);
});

test("signup and account-recovery routes use their dedicated limits", async (t) => {
  const cases = [
    { path: "/sign-up/email", max: 5, ip: "198.51.100.31" },
    { path: "/request-password-reset", max: 3, ip: "198.51.100.32" },
    { path: "/send-verification-email", max: 3, ip: "198.51.100.33" },
  ];

  for (const example of cases) {
    await t.test(example.path, async () => {
      const auth = betterAuth({
        baseURL: "http://localhost:4100",
        secret: "one-more-very-long-test-only-auth-secret",
        database: memoryAdapter({ user: [], session: [], account: [], verification: [] }),
        advanced: { ipAddress: { ipAddressHeaders: [AUTH_CLIENT_IP_HEADER] } },
        rateLimit: { ...AUTH_RATE_LIMIT, storage: "memory" },
        emailAndPassword: { enabled: true },
        emailVerification: { sendVerificationEmail: async () => undefined },
      });
      const request = () =>
        auth.handler(
          new Request(`http://localhost:4100/api/auth${example.path}`, {
            method: "POST",
            headers: {
              "content-type": "application/json",
              [AUTH_CLIENT_IP_HEADER]: example.ip,
            },
            body: "{}",
          }),
        );

      for (let attempt = 0; attempt < example.max; attempt += 1) {
        assert.notEqual((await request()).status, 429);
      }
      assert.equal((await request()).status, 429);
    });
  }
});

import { strict as assert } from "node:assert";
import { test } from "node:test";
import type { AgentRunResult } from "@superlog/db";
import { getPrDeliveryRetryEligibility } from "./pr-retry.js";

test("pr delivery retry is allowed for failed pr_open_failed runs with a pending reusable patch", () => {
  const result: AgentRunResult = {
    state: "failed",
    summary: "Failed to validate or open the PR.",
    failureReason: "pr_open_failed",
    pr: {
      selectedRepoFullName: "acme/api",
      branchName: "superlog/fix-api",
      baseBranch: "main",
      patch: "diff --git a/a b/a\n",
      validationPassed: true,
      openStatus: "pending",
    },
  };

  assert.deepEqual(
    getPrDeliveryRetryEligibility({
      state: "failed",
      failureReason: "pr_open_failed",
      result,
    }),
    { canRetry: true },
  );
});

test("pr delivery retry is denied when no patch can be reused", () => {
  const result: AgentRunResult = {
    state: "failed",
    summary: "Failed to validate or open the PR.",
    failureReason: "pr_open_failed",
    pr: {
      selectedRepoFullName: "acme/api",
      branchName: "superlog/fix-api",
      baseBranch: "main",
      validationPassed: true,
      openStatus: "pending",
    },
  };

  assert.deepEqual(
    getPrDeliveryRetryEligibility({
      state: "failed",
      failureReason: "pr_open_failed",
      result,
    }),
    { canRetry: false, reason: "agent run has no reusable patch" },
  );
});

test("pr delivery retry is denied for non PR-open failures", () => {
  assert.deepEqual(
    getPrDeliveryRetryEligibility({
      state: "failed",
      failureReason: "runtime_budget_exhausted",
      result: null,
    }),
    { canRetry: false, reason: "agent run did not fail while opening a PR" },
  );
});

export type IntegrationInstallAuthorization = "authorized" | "forbidden" | "unauthenticated";

export async function authorizeIntegrationInstall(input: {
  authenticatedUserId: string | null;
  initiatingUserId: string;
  preferredOrgId: string | null;
  projectId: string;
  canManageProject(args: {
    userId: string;
    preferredOrgId: string | null;
    projectId: string;
  }): Promise<boolean>;
}): Promise<IntegrationInstallAuthorization> {
  if (!input.authenticatedUserId) return "unauthenticated";
  if (input.authenticatedUserId !== input.initiatingUserId) return "forbidden";
  const canManage = await input.canManageProject({
    userId: input.authenticatedUserId,
    preferredOrgId: input.preferredOrgId,
    projectId: input.projectId,
  });
  return canManage ? "authorized" : "forbidden";
}

import { strict as assert } from "node:assert";
import { test } from "node:test";
import {
  cloudflarePendingWorkerDestinationReplacements,
  cloudflareWorkerDestinationRemovalSlugs,
  cloudflareWorkerWiringMode,
} from "./cloudflare-installation-policy.js";

test("a new Cloudflare connection waits for explicit Worker selection", () => {
  assert.deepEqual(cloudflareWorkerWiringMode(null), {
    autoWire: false,
    wireAfterConnect: false,
  });
});

test("a Cloudflare reconnect preserves the existing Worker wiring preference", () => {
  assert.deepEqual(cloudflareWorkerWiringMode(false), {
    autoWire: false,
    wireAfterConnect: false,
  });
  assert.deepEqual(cloudflareWorkerWiringMode(true), {
    autoWire: true,
    wireAfterConnect: true,
  });
});

test("bulk unwiring includes active and pending destination slugs", () => {
  assert.deepEqual(
    cloudflareWorkerDestinationRemovalSlugs({
      traces: "active-traces",
      logs: "active-logs",
      metrics: "active-metrics",
      __previous_traces_0: "previous-traces-a",
      __previous_traces_1: "previous-traces-b",
      __previous_logs_0: "previous-logs",
    }),
    {
      traces: ["active-traces", "previous-traces-a", "previous-traces-b"],
      logs: ["active-logs", "previous-logs"],
    },
  );
});

test("wiring retries retained destination replacements before adding active slugs", () => {
  assert.deepEqual(
    cloudflarePendingWorkerDestinationReplacements({
      traces: "active-traces",
      logs: "active-logs",
      __previous_traces_0: "previous-traces-a",
      __previous_traces_1: "previous-traces-b",
      __previous_logs_0: "previous-logs",
    }),
    [
      { traces: { from: "previous-traces-a", to: "active-traces" } },
      { traces: { from: "previous-traces-b", to: "active-traces" } },
      { logs: { from: "previous-logs", to: "active-logs" } },
    ],
  );
});

import { strict as assert } from "node:assert";
import { readFileSync } from "node:fs";
import { test } from "node:test";

const workflow = readFileSync(new URL("../.github/workflows/ci.yaml", import.meta.url), "utf8");

test("CI workflow uses least-privilege repository token permissions", () => {
  assert.match(workflow, /^permissions:\n {2}contents: read$/m);
  assert.doesNotMatch(workflow, /^permissions:\s*write-all$/m);
});

test("CI workflow pins third-party actions to immutable commit SHAs", () => {
  const actionRefs = [...workflow.matchAll(/^\s*uses:\s*([^@\s]+)@([^\s#]+)/gm)];

  assert.ok(actionRefs.length > 0, "expected workflow to use at least one action");

  for (const [, action, ref] of actionRefs) {
    assert.match(ref, /^[a-f0-9]{40}$/, `${action} is not pinned to a full commit SHA`);
  }
});

test("CI workflow checkout steps do not persist GitHub token credentials", () => {
  const checkoutBlocks = workflow
    .split(/\n(?=\s+- name: )/)
    .filter((block) => block.includes("uses: actions/checkout@"));

  assert.ok(checkoutBlocks.length > 0, "expected workflow to use checkout");

  for (const block of checkoutBlocks) {
    assert.match(block, /\n\s+persist-credentials:\s*false\b/);
  }
});

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import { shouldShowMcpPill } from "./mcpPill.ts";

test("pill stays hidden until the project + mcp status have loaded", () => {
  assert.equal(
    shouldShowMcpPill({ projectId: undefined, connected: false, dismissed: false }),
    false,
  );
  assert.equal(
    shouldShowMcpPill({ projectId: "p1", connected: undefined, dismissed: false }),
    false,
  );
});

test("pill shows when a project exists and mcp is not connected", () => {
  assert.equal(shouldShowMcpPill({ projectId: "p1", connected: false, dismissed: false }), true);
});

test("pill hides once mcp is connected", () => {
  assert.equal(shouldShowMcpPill({ projectId: "p1", connected: true, dismissed: false }), false);
});

test("pill stays hidden after the user dismisses it", () => {
  assert.equal(shouldShowMcpPill({ projectId: "p1", connected: false, dismissed: true }), false);
});

test("pill is fixed to the bottom-right and opens the install dialog", async () => {
  const source = await readFile(new URL("./McpInstallPill.tsx", import.meta.url), "utf8");
  assert.match(source, /fixed/);
  assert.match(source, /bottom-/);
  assert.match(source, /right-/);
  assert.doesNotMatch(source, /bottom-5 left-5/);
  assert.match(source, /McpInstallDialog/);
  assert.match(source, /useMcpStatus/);
});

test("pill is mounted in the authenticated app shell", async () => {
  const source = await readFile(new URL("../App.tsx", import.meta.url), "utf8");
  assert.match(source, /<McpInstallPill \/>/);
});

import assert from "node:assert/strict";
import { test } from "node:test";

// auth.ts throws at import if BETTER_AUTH_SECRET is unset, and @superlog/db
// needs DATABASE_URL (the postgres client connects lazily, so a dummy is
// enough). Mirror the other auth-adjacent tests and provide both before import.
process.env.DATABASE_URL ??= "postgres://localhost:5434/superlog";
process.env.BETTER_AUTH_SECRET ??= "test-better-auth-secret";

test("organization plugin does not gate invitations on email verification", async () => {
  const { auth } = await import("./auth.js");
  const plugins = auth.options.plugins as Array<{ id: string; options?: Record<string, unknown> }>;
  const orgPlugin = plugins.find((p) => p.id === "organization");
  assert.ok(orgPlugin, "organization plugin should be registered");

  // Better Auth defaults requireEmailVerificationOnInvitation to `true`. That
  // contradicts emailAndPassword.requireEmailVerification:false — sign-ups land
  // logged-in but unverified (the default state), and the default would lock
  // those users out of getInvitation/acceptInvitation with a FORBIDDEN that the
  // UI renders as a misleading "Invitation not found" (looks like a 404). Pin it
  // false so the invite flow matches the app's "verification is optional" stance.
  assert.equal(orgPlugin.options?.requireEmailVerificationOnInvitation, false);
});

import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { test } from "node:test";
import type { DB } from "@superlog/db";
import { resolvePublicSourceMapUploadAuth } from "./management-auth.js";

function databaseReturning(row: { id: string; projectId: string } | null): DB {
  return {
    query: {
      apiKeys: {
        async findFirst() {
          return row;
        },
      },
    },
  } as unknown as DB;
}

test("public ingest keys can authorize source map uploads for their own project", async () => {
  const projectId = randomUUID();
  const auth = await resolvePublicSourceMapUploadAuth({
    database: databaseReturning({ id: "key-1", projectId }),
    method: "POST",
    path: `/api/v1/projects/${projectId}/sourcemaps`,
    token: "sl_public_test-token",
  });

  assert.deepEqual(auth, { projectId, apiKeyId: "key-1" });
});

test("public ingest keys cannot upload source maps for another project", async () => {
  const auth = await resolvePublicSourceMapUploadAuth({
    database: databaseReturning({ id: "key-1", projectId: randomUUID() }),
    method: "POST",
    path: `/api/v1/projects/${randomUUID()}/sourcemaps`,
    token: "sl_public_test-token",
  });

  assert.equal(auth, null);
});

test("public ingest keys do not authorize other management API routes", async () => {
  const projectId = randomUUID();
  const auth = await resolvePublicSourceMapUploadAuth({
    database: databaseReturning({ id: "key-1", projectId }),
    method: "GET",
    path: `/api/v1/projects/${projectId}/api-keys`,
    token: "sl_public_test-token",
  });

  assert.equal(auth, null);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import {
  AUTH_CLIENT_IP_HEADER,
  authBehindTrustedProxy,
  requestWithAuthClientIp,
  resolveAuthClientIp,
} from "./auth-client-ip.js";

test("proxy trust is off unless the deployment explicitly sets true", () => {
  assert.equal(authBehindTrustedProxy(undefined), false);
  assert.equal(authBehindTrustedProxy("false"), false);
  assert.equal(authBehindTrustedProxy("1"), false);
  assert.equal(authBehindTrustedProxy("true"), true);
});

test("direct auth requests ignore caller-supplied forwarding headers", () => {
  assert.equal(
    resolveAuthClientIp({
      peerIp: "198.51.100.42",
      forwardedFor: "203.0.113.9",
      behindTrustedProxy: false,
    }),
    "198.51.100.42",
  );
});

test("trusted proxies identify the client from the final forwarded address", () => {
  assert.equal(
    resolveAuthClientIp({
      peerIp: "10.0.0.12",
      forwardedFor: "203.0.113.9, 198.51.100.42",
      behindTrustedProxy: true,
    }),
    "198.51.100.42",
  );
});

test("trusted proxy requests with malformed forwarding data fall back to the socket peer", () => {
  assert.equal(
    resolveAuthClientIp({
      peerIp: "10.0.0.12",
      forwardedFor: "203.0.113.9, not-an-ip",
      behindTrustedProxy: true,
    }),
    "10.0.0.12",
  );
});

test("the auth request replaces caller-supplied resolved-IP headers", () => {
